(function () {
  const ADMIN_PASSWORD = 'NA';

  // Base64 storage for the logo image
  let logoBase64 = 'data:image/jpeg;base64,';

  // ---- Company / PDF template content ----
  const COMPANY = {
    name: 'Kiran Interior',
    tagline: 'Custom Furniture & Interiors — Estimate',
    contactPhone: '9642929494',
    footerNote: 'This is an estimate; final pricing may vary after site measurement.'
  };

  const SPECIAL_INSTRUCTIONS = [
    'Outer Finishing — 1.0 mm — Virgo (High Glossy Laminate or Mat Laminate)',
    'Inner Finishing — 0.8 mm (Fabric / Half White Laminate)',
    'Ceiling: Gypsum Sheet, Ultra Channel (0.4 bottom, 0.5 patti)',
    'Profile light 1 meter is 1 point',
    'Roof light 3 meters is 1 point',
    '1 spot light is 1 point'
  ];

  const EXTRA_NOTES = [
    'Note: Only two drawers will be given in each bedroom. If more than that, it will be charged. Accessories, lockers and drawers will be charged extra. Extra locker: Rs. 3,000/- each.',
    'Items which are not included in this estimation will be charged separately — for example: extra shelves, accessories, lights, changes in sizes, and any additional work.'
  ];

  const TERMS_LIST = [
    'Design Changes — After final approval, any modification in design, size, finish, or material will be chargeable and may increase the timeline.',
    'Material Availability — If the selected material is unavailable, a similar alternative will be suggested with client approval.',
    'Timeline — Project timeline depends on site readiness, electricity, civil readiness, material supply, approvals, and timely payments.',
    'Delay Due to Client Side — If the site is not ready, payments are delayed, or changes are requested, the completion date will automatically extend.',
    'Payment Delay — Delayed payments may pause work until dues are cleared.'
  ];

  const PAYMENT_TERMS = [
    'Booking Amount — 5% (Advance)',
    'Second Payment — 40% (After Material)',
    'Third Payment — 40% (Laminate Material Time)',
    'Fourth Payment — 10% (Glass Fitting)',
    'Fifth Payment — 5% (End of Project Day)'
  ];

  const ENQUIRY_CONTACTS = [
    { name: 'Prasanna Reddy', phone: '9010969494' },
    { name: 'Estimation Department', phone: '7207989494' }
  ];

  // Default Room List
  const DEFAULT_ROOMS = [
    'Master BedRoom',
    'Living Hall',
    'Kids BedRoom',
    'Guest BedRoom',
    'Kitchen',
    'Pooja Room',
    'Dining Area',
    'Balcony'
  ];

  // Default Catalog Items
  const DEFAULT_CATALOG = [
    { id: '1', name: 'Master Bed Sliding Wardrobe', category: 'Master BedRoom', rate: 1650, image: '' },
    { id: '2', name: 'King Bed with Storage', category: 'Master BedRoom', rate: 1450, image: '' },
    { id: '3', name: 'Dressing Unit & Vanity', category: 'Master BedRoom', rate: 1200, image: '' },
    { id: '4', name: 'TV Unit - Living Hall', category: 'Living Hall', rate: 1350, image: '' },
    { id: '5', name: 'Modular Kitchen — L Shape', category: 'Kitchen', rate: 1800, image: '' },
    { id: '6', name: 'Kids Study Unit & Wardrobe', category: 'Kids BedRoom', rate: 1400, image: '' }
  ];

  // Load or Initialize Local Storage
  let rooms = JSON.parse(localStorage.getItem('ki_rooms')) || DEFAULT_ROOMS;
  let catalog = JSON.parse(localStorage.getItem('ki_catalog')) || DEFAULT_CATALOG;
  let currentEstimate = JSON.parse(localStorage.getItem('ki_estimate')) || [];
  let estimateHistory = JSON.parse(localStorage.getItem('ki_history')) || [];
  let activeEditingEstimateId = null;

  // Preload logo image to Base64
  function loadLogo() {
    // Logo is embedded directly in logoBase64 above, nothing to load.
  }

  function saveRooms() {
    localStorage.setItem('ki_rooms', JSON.stringify(rooms));
  }

  function saveCatalog() {
    localStorage.setItem('ki_catalog', JSON.stringify(catalog));
  }

  function saveEstimate() {
    localStorage.setItem('ki_estimate', JSON.stringify(currentEstimate));
  }

  // ---- Material list helpers ----
  function getMasterMaterials() {
    return localStorage.getItem('ki_materials_master') || '';
  }
  function getCurrentMaterials() {
    const el = document.getElementById('materialInput');
    return el ? el.value : (localStorage.getItem('ki_materials_current') || '');
  }
  function materialLines(text) {
    return (text || '').split('\n').map(l => l.trim()).filter(Boolean);
  }

  function saveHistory() {
    localStorage.setItem('ki_history', JSON.stringify(estimateHistory));
  }

  // Toast Notification
  function showToast(msg) {
    const toast = document.getElementById('toast');
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 3000);
  }

  // Navigation Logic
  function initNavigation() {
    const navButtons = document.querySelectorAll('nav button[data-page]');
    navButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const pageId = btn.getAttribute('data-page');
        document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
        document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
        
        const targetPage = document.getElementById(`page-${pageId}`);
        if (targetPage) targetPage.classList.add('active');
        btn.classList.add('active');
      });
    });

    const hamburger = document.getElementById('hamburger');
    const mainNav = document.getElementById('mainNav');
    if (hamburger && mainNav) {
      hamburger.addEventListener('click', () => {
        mainNav.classList.toggle('open');
      });
    }
  }

  // Populate Room Dropdowns
  function populateRoomDropdowns() {
    const roomSelect = document.getElementById('roomSelect');
    const newCategory = document.getElementById('newCategory');

    if (roomSelect) {
      const prevVal = roomSelect.value;
      roomSelect.innerHTML = rooms.map(r => `<option value="${r}">${r}</option>`).join('');
      if (rooms.includes(prevVal)) roomSelect.value = prevVal;
    }

    if (newCategory) {
      newCategory.innerHTML = rooms.map(r => `<option value="${r}">${r}</option>`).join('');
    }

    renderRoomManagerList();
    updateItemDropdown();
  }

  // Filter Items based on selected Room Dropdown
  function updateItemDropdown() {
    const roomSelect = document.getElementById('roomSelect');
    const itemSelect = document.getElementById('itemSelect');
    if (!roomSelect || !itemSelect) return;

    const selectedRoom = roomSelect.value;
    const filteredItems = catalog.filter(i => i.category === selectedRoom);

    if (filteredItems.length === 0) {
      itemSelect.innerHTML = `<option value="">No items available for ${selectedRoom}</option>`;
    } else {
      itemSelect.innerHTML = filteredItems.map(item => 
        `<option value="${item.id}" data-rate="${item.rate}">${item.name} — ₹${item.rate}/sq.ft</option>`
      ).join('');
    }
  }

  // Set default dimensions
  function setDefaultDimensions() {
    const dimH = document.getElementById('dimH');
    const dimW = document.getElementById('dimW');
    const dimD = document.getElementById('dimD');

    if (dimH && !dimH.value) dimH.value = "7";
    if (dimW) dimW.value = "2";
    if (dimD) dimD.value = "2";
  }

  // Save current active estimate into history
  function recordCurrentEstimateInHistory() {
    if (currentEstimate.length === 0) return;

    const custName = document.getElementById('custName')?.value.trim() || 'Valued Customer';
    const custPhone = document.getElementById('custPhone')?.value.trim() || '';
    const discountPct = parseFloat(document.getElementById('discountInput')?.value) || 0;

    let subtotal = 0;
    currentEstimate.forEach(item => {
      subtotal += Math.round(item.h * item.w * item.rate);
    });
    const discountAmt = Math.round((subtotal * discountPct) / 100);
    const grandTotal = subtotal - discountAmt;

    if (activeEditingEstimateId) {
      const idx = estimateHistory.findIndex(e => e.id === activeEditingEstimateId);
      if (idx !== -1) {
        estimateHistory[idx] = {
          ...estimateHistory[idx],
          custName,
          custPhone,
          discountPct,
          materials: getCurrentMaterials(),
          items: [...currentEstimate],
          grandTotal,
          timestamp: new Date().toLocaleString()
        };
      }
    } else {
      const newEntry = {
        id: Date.now().toString(),
        custName,
        custPhone,
        discountPct,
        materials: getCurrentMaterials(),
        items: [...currentEstimate],
        grandTotal,
        timestamp: new Date().toLocaleString()
      };
      estimateHistory.unshift(newEntry);
      if (estimateHistory.length > 20) {
        estimateHistory = estimateHistory.slice(0, 20);
      }
      activeEditingEstimateId = newEntry.id;
    }

    saveHistory();
    renderEstimateHistoryList();
    updateEditingBanner();
  }

  // Update Editing Mode Banner on Estimate Page
  function updateEditingBanner() {
    const banner = document.getElementById('editingBanner');
    const text = document.getElementById('editingBannerText');
    if (!banner || !text) return;

    if (activeEditingEstimateId) {
      const activeEst = estimateHistory.find(e => e.id === activeEditingEstimateId);
      text.textContent = `✏️ Editing saved estimate for "${activeEst ? activeEst.custName : 'Customer'}"`;
      banner.style.display = 'flex';
    } else {
      banner.style.display = 'none';
    }
  }

  // Render Admin Room List
  function renderRoomManagerList() {
    const container = document.getElementById('roomListContainer');
    if (!container) return;

    container.innerHTML = rooms.map(room => `
      <span style="background:var(--bg-panel, #f3f4f6); padding:6px 12px; border-radius:20px; display:inline-flex; align-items:center; gap:8px; border:1px solid #ddd;">
        ${room}
        <button type="button" data-room="${room}" class="delete-room-btn" style="background:none; border:none; color:red; cursor:pointer; font-weight:bold;">×</button>
      </span>
    `).join('');

    container.querySelectorAll('.delete-room-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const roomToDelete = e.target.getAttribute('data-room');
        rooms = rooms.filter(r => r !== roomToDelete);
        saveRooms();
        populateRoomDropdowns();
        showToast(`Room '${roomToDelete}' removed`);
      });
    });
  }

  // Render Gallery Page
  function renderGallery() {
    const grid = document.getElementById('galleryGrid');
    if (!grid) return;

    grid.innerHTML = catalog.map(item => `
      <div class="card">
        ${item.image ? `<img src="${item.image}" alt="${item.name}">` : '<div class="img-placeholder">No Image Available</div>'}
        <div class="card-body">
          <span class="chip">${item.category}</span>
          <h3>${item.name}</h3>
          <p class="price">Starting at ₹${item.rate} / sq.ft</p>
        </div>
      </div>
    `).join('');
  }

  // Render Estimate Table Grouped by Room
  function renderEstimateTable() {
    const tbody = document.getElementById('estimateBody');
    const subtotalCell = document.getElementById('subtotalCell');
    const discountCell = document.getElementById('discountCell');
    const grandTotalCell = document.getElementById('grandTotal');
    const discountInput = document.getElementById('discountInput');

    if (!tbody) return;

    if (currentEstimate.length === 0) {
      tbody.innerHTML = `<tr><td colspan="6" class="empty">No items added yet.</td></tr>`;
      if (subtotalCell) subtotalCell.textContent = '₹0';
      if (discountCell) discountCell.textContent = '− ₹0';
      if (grandTotalCell) grandTotalCell.textContent = '₹0';
      return;
    }

    const groupedByRoom = currentEstimate.reduce((acc, row, index) => {
      if (!acc[row.room]) acc[row.room] = [];
      acc[row.room].push({ ...row, originalIndex: index });
      return acc;
    }, {});

    let subtotal = 0;
    let html = '';

    for (const [roomName, items] of Object.entries(groupedByRoom)) {
      let roomSubtotal = 0;

      html += `
        <tr class="room-header-row" style="background-color: #f0f4f8; font-weight: bold;">
          <td colspan="6" style="padding: 8px; font-size: 1.05em; color: #1a2b4c;">
            🏠 ${roomName}
          </td>
        </tr>
      `;

      items.forEach(row => {
        const sqft = (row.h * row.w).toFixed(1);
        const amount = Math.round(sqft * row.rate);
        roomSubtotal += amount;
        subtotal += amount;

        html += `
          <tr>
            <td style="padding-left: 20px;">${row.name}</td>
            <td>${row.custom ? '—' : `${row.h} × ${row.w} × ${row.d}`}</td>
            <td>${row.custom ? '—' : sqft}</td>
            <td>${row.custom ? 'Fixed' : '₹' + row.rate}</td>
            <td>₹${amount.toLocaleString('en-IN')}</td>
            <td><button data-idx="${row.originalIndex}" class="remove-item-btn" style="color:red; background:none; border:none; cursor:pointer;">✕</button></td>
          </tr>
        `;
      });

      html += `
        <tr style="border-bottom: 2px solid #ddd; font-style: italic; background-color: #fafafa;">
          <td colspan="4" style="text-align: right; font-weight: 500;">${roomName} Subtotal:</td>
          <td colspan="2" style="font-weight: bold;">₹${roomSubtotal.toLocaleString('en-IN')}</td>
        </tr>
      `;
    }

    tbody.innerHTML = html;

    const discountPct = parseFloat(discountInput ? discountInput.value : 0) || 0;
    const discountAmt = Math.round((subtotal * discountPct) / 100);
    const grandTotal = subtotal - discountAmt;

    if (subtotalCell) subtotalCell.textContent = `₹${subtotal.toLocaleString('en-IN')}`;
    if (discountCell) discountCell.textContent = `− ₹${discountAmt.toLocaleString('en-IN')}`;
    if (grandTotalCell) grandTotalCell.textContent = `₹${grandTotal.toLocaleString('en-IN')}`;

    tbody.querySelectorAll('.remove-item-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.target.getAttribute('data-idx'));
        currentEstimate.splice(idx, 1);
        saveEstimate();
        recordCurrentEstimateInHistory();
        renderEstimateTable();
      });
    });
  }

  // WhatsApp Share Functionality
  function shareOnWhatsApp() {
    if (currentEstimate.length === 0) {
      showToast('Add items to estimate first');
      return;
    }

    const custName = document.getElementById('custName')?.value.trim() || 'Valued Customer';
    const custPhone = document.getElementById('custPhone')?.value.trim() || '';
    const discountPct = parseFloat(document.getElementById('discountInput')?.value) || 0;

    const groupedByRoom = currentEstimate.reduce((acc, item) => {
      if (!acc[item.room]) acc[item.room] = [];
      acc[item.room].push(item);
      return acc;
    }, {});

    let message = `*Kiran Interior — Estimate*\n`;
    message += `👤 *Customer:* ${custName}\n`;
    if (custPhone) message += `📞 *Phone:* ${custPhone}\n`;
    message += `-----------------------------------\n\n`;

    let subtotal = 0;

    for (const [room, items] of Object.entries(groupedByRoom)) {
      message += `🏠 *${room.toUpperCase()}*\n`;
      let roomTotal = 0;

      items.forEach(item => {
        const sqft = (item.h * item.w).toFixed(1);
        const amount = Math.round(sqft * item.rate);
        roomTotal += amount;
        subtotal += amount;

        message += `  • ${item.name}\n`;
        if (item.custom) {
          message += `    Fixed amount = ₹${amount.toLocaleString('en-IN')}\n`;
        } else {
          message += `    Size: ${item.h}' x ${item.w}' (${sqft} sq.ft) @ ₹${item.rate}/sq.ft = ₹${amount.toLocaleString('en-IN')}\n`;
        }
      });

      message += `  *${room} Subtotal:* ₹${roomTotal.toLocaleString('en-IN')}\n\n`;
    }

    const discountAmt = Math.round((subtotal * discountPct) / 100);
    const grandTotal = subtotal - discountAmt;

    message += `-----------------------------------\n`;
    message += `*Subtotal:* ₹${subtotal.toLocaleString('en-IN')}\n`;
    if (discountPct > 0) {
      message += `*Discount (${discountPct}%):* -₹${discountAmt.toLocaleString('en-IN')}\n`;
    }
    message += `💰 *Grand Total:* ₹${grandTotal.toLocaleString('en-IN')}\n`;
    message += `-----------------------------------\n`;
    message += `Thank you for choosing Kiran Interior!`;

    recordCurrentEstimateInHistory();

    const encodedMessage = encodeURIComponent(message);
    const whatsappUrl = custPhone 
      ? `https://api.whatsapp.com/send?phone=${custPhone.replace(/\D/g, '')}&text=${encodedMessage}`
      : `https://api.whatsapp.com/send?text=${encodedMessage}`;

    window.open(whatsappUrl, '_blank');
  }

  // ---- PDF helpers ----

  // Header banner render function with embedded image logo
  function drawPdfBanner(doc, titleText, subtitleText) {
    // Black banner matches the logo background so the logo blends in seamlessly
    doc.setFillColor(0, 0, 0);
    doc.rect(0, 0, 210, 30, 'F');
    doc.setDrawColor(184, 134, 63);
    doc.line(0, 30, 210, 30);

    if (logoBase64) {
      doc.addImage(logoBase64, 'JPEG', 8, 1, 28, 28);
    }

    doc.setTextColor(231, 190, 100);
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(16);
    doc.text(titleText, 40, 17);
    doc.setTextColor(255, 255, 255);
    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(9);
    doc.text(subtitleText, 40, 24);
  }

  function drawPdfFooter(doc) {
    doc.setDrawColor(220);
    doc.line(14, 282, 196, 282);
    doc.setFont('Helvetica', 'italic');
    doc.setFontSize(8);
    doc.setTextColor(120);
    doc.text(COMPANY.footerNote, 14, 288);
    doc.setFont('Helvetica', 'bold');
    doc.setTextColor(50);
    doc.text(`Contact ${COMPANY.name}: ${COMPANY.contactPhone}`, 14, 294);
  }

  function generateEstimateRef() {
    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const yy = String(now.getFullYear()).slice(-2);
    return `KI-${yy}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
  }

  function drawTableColumnHeader(doc, yPos) {
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(0);
    doc.text('Item', 16, yPos);
    doc.text('H x W x D (ft)', 95, yPos);
    doc.text('Sq.ft', 140, yPos);
    doc.text('Rate/sqft', 158, yPos);
    doc.text('Amount', 180, yPos);
    doc.setDrawColor(200);
    doc.line(14, yPos + 3, 196, yPos + 3);
    return yPos + 11;
  }

  // PDF Generation Functionality
  function generatePDF() {
    if (currentEstimate.length === 0) {
      showToast('Add items to estimate first');
      return;
    }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    const custName = document.getElementById('custName')?.value.trim() || 'Valued Customer';
    const custPhone = document.getElementById('custPhone')?.value.trim() || 'N/A';
    const discountPct = parseFloat(document.getElementById('discountInput')?.value) || 0;
    const ref = generateEstimateRef();

    // ---- Page 1: Estimate ----
    drawPdfBanner(doc, COMPANY.name, COMPANY.tagline);

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(0);
    doc.text(`Customer: ${custName}`, 14, 34);
    doc.text(`Phone: ${custPhone}`, 14, 40);

    doc.setTextColor(100);
    doc.text(`Date: ${new Date().toLocaleDateString('en-GB')}`, 196, 34, { align: 'right' });
    doc.setFontSize(8);
    doc.text(`Ref: ${ref}`, 196, 39, { align: 'right' });

    doc.setDrawColor(200);
    doc.line(14, 46, 196, 46);

    let yPos = drawTableColumnHeader(doc, 52);

    const groupedByRoom = currentEstimate.reduce((acc, item) => {
      if (!acc[item.room]) acc[item.room] = [];
      acc[item.room].push(item);
      return acc;
    }, {});

    let subtotal = 0;

    const startNewPage = () => {
      doc.addPage();
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(11);
      doc.setTextColor(93, 58, 32);
      doc.text(`${COMPANY.name} — Estimate (contd.)`, 14, 16);
      return drawTableColumnHeader(doc, 26);
    };

    for (const [room, items] of Object.entries(groupedByRoom)) {
      if (yPos > 255) yPos = startNewPage();

      doc.setFillColor(224, 196, 150);
      doc.rect(14, yPos - 5, 182, 7, 'F');
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(80, 50, 20);
      doc.text(room.toUpperCase(), 16, yPos);
      yPos += 9;

      let roomSubtotal = 0;

      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(9);
      doc.setTextColor(0);
      items.forEach(item => {
        if (yPos > 265) yPos = startNewPage();
        const sqft = (item.h * item.w).toFixed(1);
        const amount = Math.round(sqft * item.rate);
        roomSubtotal += amount;

        doc.text(item.name, 16, yPos);
        doc.text(item.custom ? '-' : `${item.h} x ${item.w} x ${item.d}`, 95, yPos);
        doc.text(item.custom ? '-' : `${sqft}`, 140, yPos);
        doc.text(item.custom ? 'Fixed' : `Rs.${item.rate}`, 158, yPos);
        doc.text(`Rs.${amount.toLocaleString('en-IN')}`, 180, yPos);
        yPos += 7;
      });

      subtotal += roomSubtotal;

      if (yPos > 265) yPos = startNewPage();
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(80, 50, 20);
      doc.text(`${room} subtotal: Rs.${roomSubtotal.toLocaleString('en-IN')}`, 105, yPos, { align: 'center' });
      yPos += 10;
    }

    const discountAmt = Math.round((subtotal * discountPct) / 100);
    const grandTotal = subtotal - discountAmt;

    if (yPos > 255) yPos = startNewPage();
    doc.setDrawColor(180);
    doc.line(14, yPos - 4, 196, yPos - 4);
    yPos += 4;

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(0);
    doc.text('Subtotal:', 150, yPos);
    doc.text(`Rs.${subtotal.toLocaleString('en-IN')}`, 196, yPos, { align: 'right' });
    yPos += 6;

    if (discountPct > 0) {
      doc.setTextColor(180, 50, 40);
      doc.text(`Discount (${discountPct}%):`, 150, yPos);
      doc.text(`- Rs.${discountAmt.toLocaleString('en-IN')}`, 196, yPos, { align: 'right' });
      yPos += 6;
    }

    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(13);
    doc.setTextColor(80, 50, 20);
    doc.text('Grand Total:', 150, yPos);
    doc.text(`Rs.${grandTotal.toLocaleString('en-IN')}`, 196, yPos, { align: 'right' });

    drawPdfFooter(doc);

    // ---- Page 2: Terms & Conditions ----
    doc.addPage();
    drawPdfBanner(doc, 'Terms & Conditions', COMPANY.name);

    let ty = 36;
    const bodyWidth = 182;

    // Start a new page if the next block will not fit
    const ensure = (need) => {
      if (ty + need > 278) {
        doc.addPage();
        ty = 20;
      }
    };

    // ---- Material list (above Terms & Conditions) ----
    const pdfMaterials = materialLines(getCurrentMaterials());
    if (pdfMaterials.length) {
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(12);
      doc.setTextColor(80, 50, 20);
      doc.text('Material List', 14, ty);
      ty += 8;

      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(9.5);
      doc.setTextColor(30);
      pdfMaterials.forEach(m => {
        const wrapped = doc.splitTextToSize(`• ${m}`, bodyWidth - 4);
        ensure(wrapped.length * 5 + 2);
        doc.text(wrapped, 16, ty);
        ty += wrapped.length * 5 + 1.5;
      });
      ty += 6;
    }

    ensure(30);
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(80, 50, 20);
    doc.text('Note & Special Instructions', 14, ty);
    ty += 8;

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(9.5);
    doc.setTextColor(30);
    SPECIAL_INSTRUCTIONS.forEach(line => {
      ensure(8);
      doc.text(`• ${line}`, 16, ty);
      ty += 6;
    });
    ty += 2;

    EXTRA_NOTES.forEach(note => {
      const wrapped = doc.splitTextToSize(note, bodyWidth);
      ensure(wrapped.length * 5 + 4);
      doc.text(wrapped, 14, ty);
      ty += wrapped.length * 5 + 4;
    });

    ensure(30);
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(80, 50, 20);
    doc.text('Terms & Conditions', 14, ty);
    ty += 8;

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(9.5);
    doc.setTextColor(30);
    TERMS_LIST.forEach((t, i) => {
      const wrapped = doc.splitTextToSize(`${i + 1}. ${t}`, bodyWidth);
      ensure(wrapped.length * 5 + 3);
      doc.text(wrapped, 14, ty);
      ty += wrapped.length * 5 + 3;
    });
    ty += 2;

    ensure(30);
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(80, 50, 20);
    doc.text('Payment & Conditions', 14, ty);
    ty += 8;

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(9.5);
    doc.setTextColor(30);
    PAYMENT_TERMS.forEach((t, i) => {
      ensure(8);
      doc.text(`${i + 1}. ${t}`, 16, ty);
      ty += 6;
    });
    ty += 6;

    ensure(30);
    doc.setDrawColor(200);
    doc.line(14, ty, 196, ty);
    ty += 8;

    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(0);
    doc.text('For any enquiry, please call:', 14, ty);
    ty += 6;

    doc.setFont('Helvetica', 'normal');
    ENQUIRY_CONTACTS.forEach(c => {
      doc.text(`${c.name} — ${c.phone}`, 14, ty);
      ty += 6;
    });

    recordCurrentEstimateInHistory();

    doc.save(`Kiran_Interior_Estimate_${custName.replace(/\s+/g, '_')}.pdf`);
  }

  // Initialize Calculator / Estimate listeners
  function initEstimateLogic() {
    const roomSelect = document.getElementById('roomSelect');
    const addItemBtn = document.getElementById('addItemBtn');
    const discountInput = document.getElementById('discountInput');
    const clearBtn = document.getElementById('clearBtn');
    const whatsappBtn = document.getElementById('whatsappBtn');
    const downloadPdfBtn = document.getElementById('downloadPdfBtn');
    const startNewBtn = document.getElementById('startNewBtn');
    const custNameInput = document.getElementById('custName');
    const custPhoneInput = document.getElementById('custPhone');

    if (roomSelect) {
      roomSelect.addEventListener('change', updateItemDropdown);
    }

    if (addItemBtn) {
      addItemBtn.addEventListener('click', () => {
        const room = document.getElementById('roomSelect').value;
        const itemSelect = document.getElementById('itemSelect');
        const itemId = itemSelect.value;
        const selectedOpt = itemSelect.options[itemSelect.selectedIndex];

        if (!itemId) {
          showToast('Please select a valid item');
          return;
        }

        const itemData = catalog.find(i => i.id === itemId);
        const h = parseFloat(document.getElementById('dimH').value) || 0;
        const w = parseFloat(document.getElementById('dimW').value) || 0;
        const d = parseFloat(document.getElementById('dimD').value) || 0;

        if (h <= 0 || w <= 0) {
          showToast('Height and Width must be greater than 0');
          return;
        }

        currentEstimate.push({
          room: room,
          name: itemData ? itemData.name : selectedOpt.text,
          rate: itemData ? itemData.rate : parseFloat(selectedOpt.getAttribute('data-rate')),
          h: h,
          w: w,
          d: d
        });

        saveEstimate();
        recordCurrentEstimateInHistory();
        renderEstimateTable();
        showToast('Item added to estimate');
      });
    }

    const addOtherBtn = document.getElementById('addOtherBtn');
    if (addOtherBtn) {
      addOtherBtn.addEventListener('click', () => {
        const room = document.getElementById('roomSelect').value;
        const nameEl = document.getElementById('otherName');
        const amountEl = document.getElementById('otherAmount');
        const name = nameEl.value.trim();
        const amount = parseFloat(amountEl.value);

        if (!room) { showToast('Please select a Room / Area first'); return; }
        if (!name) { showToast('Please enter the item name'); return; }
        if (isNaN(amount) || amount <= 0) { showToast('Please enter a valid amount'); return; }

        // Stored as 1 x 1 sq.ft at the given amount so totals, history,
        // invoice and agreement pages all calculate it correctly.
        currentEstimate.push({
          room: room,
          name: name,
          custom: true,
          rate: amount,
          h: 1,
          w: 1,
          d: 0
        });

        nameEl.value = '';
        amountEl.value = '';
        saveEstimate();
        recordCurrentEstimateInHistory();
        renderEstimateTable();
        showToast('Other item added to estimate');
      });
    }

    if (discountInput) {
      discountInput.addEventListener('input', () => {
        renderEstimateTable();
        recordCurrentEstimateInHistory();
      });
    }

    if (custNameInput) {
      custNameInput.addEventListener('input', recordCurrentEstimateInHistory);
    }

    if (custPhoneInput) {
      custPhoneInput.addEventListener('input', recordCurrentEstimateInHistory);
    }

    document.querySelectorAll('.chip[data-pct]').forEach(chip => {
      chip.addEventListener('click', () => {
        const pct = chip.getAttribute('data-pct');
        if (discountInput) {
          discountInput.value = pct;
          renderEstimateTable();
          recordCurrentEstimateInHistory();
        }
      });
    });

    if (clearBtn) {
      clearBtn.addEventListener('click', () => {
        currentEstimate = [];
        activeEditingEstimateId = null;
        saveEstimate();
        updateEditingBanner();
        renderEstimateTable();
        showToast('Estimate cleared');
      });
    }

    if (startNewBtn) {
      startNewBtn.addEventListener('click', () => {
        currentEstimate = [];
        activeEditingEstimateId = null;
        if (custNameInput) custNameInput.value = '';
        if (custPhoneInput) custPhoneInput.value = '';
        if (discountInput) discountInput.value = '0';
        const matBox = document.getElementById('materialInput');
        if (matBox) {
          matBox.value = getMasterMaterials();
          localStorage.setItem('ki_materials_current', matBox.value);
        }
        saveEstimate();
        updateEditingBanner();
        renderEstimateTable();
        showToast('Started new estimate');
      });
    }

    if (whatsappBtn) {
      whatsappBtn.addEventListener('click', shareOnWhatsApp);
    }

    if (downloadPdfBtn) {
      downloadPdfBtn.addEventListener('click', generatePDF);
    }
  }

  // Material list: estimate-page box + admin default list
  function initMaterials() {
    const matBox = document.getElementById('materialInput');
    const master = document.getElementById('masterMaterials');
    const saveBtn = document.getElementById('saveMaterialsBtn');

    if (matBox) {
      const saved = localStorage.getItem('ki_materials_current');
      matBox.value = (saved !== null) ? saved : getMasterMaterials();
      matBox.addEventListener('input', () => {
        localStorage.setItem('ki_materials_current', matBox.value);
        recordCurrentEstimateInHistory();
      });
    }

    if (master) master.value = getMasterMaterials();

    if (saveBtn) {
      saveBtn.addEventListener('click', () => {
        const oldMaster = getMasterMaterials();
        localStorage.setItem('ki_materials_master', master.value);
        // Refresh the estimate-page box unless the person already customised it
        if (matBox && !activeEditingEstimateId && (matBox.value === oldMaster || matBox.value === '')) {
          matBox.value = master.value;
          localStorage.setItem('ki_materials_current', matBox.value);
        }
        showToast('Material list saved');
      });
    }
  }

  // Admin Section Logic
  function initAdminLogic() {
    const adminPass = document.getElementById('adminPass');
    const adminLoginBtn = document.getElementById('adminLoginBtn');
    const adminGate = document.getElementById('adminGate');
    const adminPanel = document.getElementById('adminPanel');

    if (adminLoginBtn) {
      adminLoginBtn.addEventListener('click', () => {
        if (adminPass.value === ADMIN_PASSWORD) {
          adminGate.style.display = 'none';
          adminPanel.style.display = 'block';
          renderAdminCatalog();
          renderEstimateHistoryList();
        } else {
          showToast('Incorrect Password');
        }
      });
    }

    const addRoomBtn = document.getElementById('addRoomBtn');
    if (addRoomBtn) {
      addRoomBtn.addEventListener('click', () => {
        const newRoomInput = document.getElementById('newRoomName');
        const roomName = newRoomInput.value.trim();
        if (!roomName) {
          showToast('Enter a valid room name');
          return;
        }
        if (rooms.includes(roomName)) {
          showToast('Room already exists');
          return;
        }

        rooms.push(roomName);
        saveRooms();
        populateRoomDropdowns();
        newRoomInput.value = '';
        showToast(`Room '${roomName}' added!`);
      });
    }

    const newImage = document.getElementById('newImage');
    const newImagePreview = document.getElementById('newImagePreview');
    let uploadedImageBase64 = '';

    if (newImage) {
      newImage.addEventListener('change', (e) => {
        const file = e.target.files[0];
        if (file) {
          const reader = new FileReader();
          reader.onload = function (event) {
            uploadedImageBase64 = event.target.result;
            if (newImagePreview) {
              newImagePreview.src = uploadedImageBase64;
              newImagePreview.style.display = 'block';
            }
          };
          reader.readAsDataURL(file);
        }
      });
    }

    const addCatalogBtn = document.getElementById('addCatalogBtn');
    if (addCatalogBtn) {
      addCatalogBtn.addEventListener('click', () => {
        const name = document.getElementById('newName').value.trim();
        const category = document.getElementById('newCategory').value;
        const rate = parseFloat(document.getElementById('newRate').value);

        if (!name || isNaN(rate)) {
          showToast('Please provide a valid item name and rate');
          return;
        }

        const newItem = {
          id: Date.now().toString(),
          name: name,
          category: category,
          rate: rate,
          image: uploadedImageBase64
        };

        catalog.push(newItem);
        saveCatalog();
        renderGallery();
        renderAdminCatalog();
        updateItemDropdown();

        document.getElementById('newName').value = '';
        document.getElementById('newRate').value = '';
        document.getElementById('newImage').value = '';
        if (newImagePreview) newImagePreview.style.display = 'none';
        uploadedImageBase64 = '';

        showToast('Catalog item added');
      });
    }
  }

  // Render Admin Item Catalog List
  function renderAdminCatalog() {
    const adminList = document.getElementById('adminList');
    if (!adminList) return;

    adminList.innerHTML = catalog.map(item => `
      <div style="display:flex; flex-direction:column; gap:8px; padding:12px; border-bottom:1px solid #eee; background:#fff; margin-bottom:8px; border-radius:6px;" id="catalog-row-${item.id}">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div>
            <strong>${item.name}</strong> <span style="color:#666">(${item.category})</span>
            <div>₹${item.rate} / sq.ft</div>
          </div>
          <div style="display:flex; gap:8px;">
            <button data-id="${item.id}" class="edit-item-btn" style="color:#1a2b4c; background:none; border:1px solid #1a2b4c; padding:4px 10px; border-radius:4px; cursor:pointer;">Edit</button>
            <button data-id="${item.id}" class="delete-item-btn" style="color:red; background:none; border:1px solid red; padding:4px 10px; border-radius:4px; cursor:pointer;">Delete</button>
          </div>
        </div>

        <div id="edit-form-${item.id}" style="display:none; margin-top:8px; padding-top:8px; border-top:1px dashed #ccc;">
          <div style="display:grid; grid-template-columns:1fr 1fr 1fr; gap:8px;">
            <div>
              <label style="font-size:0.8em; margin:0;">Item Name</label>
              <input type="text" id="edit-name-${item.id}" value="${item.name}">
            </div>
            <div>
              <label style="font-size:0.8em; margin:0;">Room Category</label>
              <select id="edit-cat-${item.id}">
                ${rooms.map(r => `<option value="${r}" ${r === item.category ? 'selected' : ''}>${r}</option>`).join('')}
              </select>
            </div>
            <div>
              <label style="font-size:0.8em; margin:0;">Rate (₹/sq.ft)</label>
              <input type="number" id="edit-rate-${item.id}" value="${item.rate}">
            </div>
          </div>
          <div style="display:flex; gap:8px; margin-top:8px; justify-content:flex-end;">
            <button data-id="${item.id}" class="cancel-edit-btn ghost" style="padding:4px 8px;">Cancel</button>
            <button data-id="${item.id}" class="save-edit-btn primary" style="padding:4px 12px; margin:0;">Save Changes</button>
          </div>
        </div>
      </div>
    `).join('');

    adminList.querySelectorAll('.edit-item-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const editForm = document.getElementById(`edit-form-${id}`);
        if (editForm) editForm.style.display = editForm.style.display === 'none' ? 'block' : 'none';
      });
    });

    adminList.querySelectorAll('.cancel-edit-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const editForm = document.getElementById(`edit-form-${id}`);
        if (editForm) editForm.style.display = 'none';
      });
    });

    adminList.querySelectorAll('.save-edit-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const newName = document.getElementById(`edit-name-${id}`)?.value.trim();
        const newCat = document.getElementById(`edit-cat-${id}`)?.value;
        const newRate = parseFloat(document.getElementById(`edit-rate-${id}`)?.value);

        if (!newName || isNaN(newRate)) {
          showToast('Invalid name or rate');
          return;
        }

        const item = catalog.find(i => i.id === id);
        if (item) {
          item.name = newName;
          item.category = newCat;
          item.rate = newRate;

          saveCatalog();
          renderGallery();
          renderAdminCatalog();
          updateItemDropdown();
          showToast('Item updated successfully');
        }
      });
    });

    adminList.querySelectorAll('.delete-item-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        catalog = catalog.filter(i => i.id !== id);
        saveCatalog();
        renderGallery();
        renderAdminCatalog();
        updateItemDropdown();
        showToast('Item deleted from catalog');
      });
    });
  }

  // Render Estimates History List
  function renderEstimateHistoryList() {
    const historyList = document.getElementById('estimateHistoryList');
    if (!historyList) return;

    if (estimateHistory.length === 0) {
      historyList.innerHTML = `<p style="color:#666;">No saved estimates found.</p>`;
      return;
    }

    historyList.innerHTML = estimateHistory.map(est => `
      <div style="border:1px solid #ddd; padding:12px; border-radius:6px; background:#fff; margin-bottom:10px;">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div>
            <strong>${est.custName}</strong> ${est.custPhone ? `(${est.custPhone})` : ''}
            <div style="font-size:0.85em; color:#666;">${est.timestamp} — ${est.items.length} item(s)</div>
          </div>
          <div style="text-align:right;">
            <div style="font-weight:bold; color:#1a2b4c; font-size:1.1em;">₹${est.grandTotal.toLocaleString('en-IN')}</div>
            <div style="display:flex; gap:6px; margin-top:4px;">
              <button data-id="${est.id}" class="load-estimate-btn primary" style="padding:4px 8px; font-size:0.85em; margin:0;">Edit/Load</button>
              <button data-id="${est.id}" class="generate-invoice-btn" style="padding:4px 8px; font-size:0.85em; margin:0; background:#5d3a20; color:#fff; border-radius:4px; cursor:pointer;">Generate Invoice</button>
              <button data-id="${est.id}" class="generate-agreement-btn" style="padding:4px 8px; font-size:0.85em; margin:0; background:#1a2b4c; color:#fff; border-radius:4px; cursor:pointer;">Agreement</button>
              <button data-id="${est.id}" class="delete-estimate-btn" style="padding:4px 8px; font-size:0.85em; background:none; border:1px solid red; color:red; border-radius:4px; cursor:pointer;">Delete</button>
            </div>
          </div>
        </div>
      </div>
    `).join('');

    historyList.querySelectorAll('.load-estimate-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const est = estimateHistory.find(item => item.id === id);

        if (est) {
          currentEstimate = [...est.items];
          activeEditingEstimateId = est.id;

          const custNameInput = document.getElementById('custName');
          const custPhoneInput = document.getElementById('custPhone');
          const discountInput = document.getElementById('discountInput');

          if (custNameInput) custNameInput.value = est.custName || '';
          if (custPhoneInput) custPhoneInput.value = est.custPhone || '';
          if (discountInput) discountInput.value = est.discountPct || 0;
          const matBox = document.getElementById('materialInput');
          if (matBox) {
            matBox.value = (est.materials !== undefined) ? est.materials : getMasterMaterials();
            localStorage.setItem('ki_materials_current', matBox.value);
          }

          saveEstimate();
          renderEstimateTable();
          updateEditingBanner();

          const quoteBtn = document.querySelector('nav button[data-page="quote"]');
          if (quoteBtn) quoteBtn.click();

          showToast(`Loaded estimate for ${est.custName}`);
        }
      });
    });

    historyList.querySelectorAll('.generate-invoice-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const est = estimateHistory.find(item => item.id === id);
        if (!est) return;

        // Pass the selected saved estimate (with its material list) to the invoice page.
        localStorage.setItem('ki_invoice_estimate', JSON.stringify({ ...est, materials: (est.materials !== undefined ? est.materials : getMasterMaterials()) }));
        window.open('invoice.html', '_blank');
      });
    });

    historyList.querySelectorAll('.generate-agreement-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        const est = estimateHistory.find(item => item.id === id);
        if (!est) return;
        localStorage.setItem('ki_invoice_estimate', JSON.stringify({ ...est, materials: (est.materials !== undefined ? est.materials : getMasterMaterials()) }));
        window.open('agreement.html', '_blank');
      });
    });

    historyList.querySelectorAll('.delete-estimate-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.getAttribute('data-id');
        estimateHistory = estimateHistory.filter(item => item.id !== id);

        if (activeEditingEstimateId === id) {
          activeEditingEstimateId = null;
          updateEditingBanner();
        }

        saveHistory();
        renderEstimateHistoryList();
        showToast('Estimate deleted from history');
      });
    });
  }

  // Document Ready Initialization
  document.addEventListener('DOMContentLoaded', () => {
    loadLogo();
    initMaterials();
    initNavigation();
    populateRoomDropdowns();
    setDefaultDimensions();
    renderGallery();
    renderEstimateTable();
    updateEditingBanner();
    initEstimateLogic();
    initAdminLogic();
  });
})();